<section class="page-hero compact"><p class="eyebrow">YOUR READING BAG</p><h1>Cart</h1></section><section class="section cart"><div><?php foreach($books as $book):?><article class="cart-row"><div class="cover cover-<?=($book['id']%5)+1?> mini"><span><?=Security::e($book['title'])?></span></div><div><h2><?=Security::e($book['title'])?></h2><p><?=Security::e($book['author_name'])?></p></div><strong>$<?=number_format((float)($book['sale_price']?:$book['price']),2)?></strong><form action="/cart/remove" method="post"><input type="hidden" name="_token" value="<?=Security::csrf()?>"><input type="hidden" name="book_id" value="<?=$book['id']?>"><button class="text-button">Remove</button></form></article><?php endforeach;?><?php if(!$books):?><div class="empty"><h2>Your bag is empty</h2><p>Start a new reading adventure in the Archon library.</p><a class="button" href="/ebooks">Browse eBooks</a></div><?php endif;?></div><?php if($books):?><aside class="order-summary"><h2>Order summary</h2><p><span>Subtotal</span><b>$<?=number_format($subtotal,2)?></b></p><?php if($coupon):?><p><span>Coupon <?=Security::e($coupon['code'])?></span><b>-$<?=number_format($discount,2)?></b></p><form method="post" action="/cart/coupon/remove"><input type="hidden" name="_token" value="<?=Security::csrf()?>"><button class="text-button">Remove coupon</button></form><?php else:?><form method="post" action="/cart/coupon" class="coupon-form"><input type="hidden" name="_token" value="<?=Security::csrf()?>"><input name="code" placeholder="Coupon code" maxlength="50"><button class="text-button">Apply</button></form><?php endif;?><p><span>Tax</span><b>Calculated at checkout</b></p><hr><p class="total"><span>Total</span><b>$<?=number_format($total,2)?></b></p><a class="button" href="/checkout">Proceed to checkout</a><a href="/ebooks">Continue shopping</a></aside><?php endif;?></section>
